import type { Schema as RootData } from './schema';

export type SectArchive = RootData['宗门档案'][string];
export type SpiritStones = SectArchive['仓库']['灵石'];

type PayrollPackage = SectArchive['俸禄']['制度'][string];
type BackpackItem = RootData['主角']['背包'][string];

export type PayrollPreview = {
  结算期: string;
  参与人数: number;
  应发灵石: SpiritStones;
  应发灵石折合下品: number;
  可发灵石折合下品: number;
  欠付灵石折合下品: number;
  应发物资: Record<string, number>;
  可发物资: Record<string, number>;
  欠付物资: Record<string, number>;
  缺失档位: string[];
};

export type PayrollSettlementResult =
  | { ok: true; sect: SectArchive; preview: PayrollPreview }
  | { ok: false; reason: string };

export type PersonalPayrollResult =
  | {
      ok: true;
      data: RootData;
      实发灵石折合下品: number;
      实发物资: Record<string, number>;
      欠付灵石折合下品: number;
      欠付物资: Record<string, number>;
    }
  | { ok: false; reason: string };

export const SPIRIT_STONE_RATES = {
  下品: 1,
  中品: 100,
  上品: 10_000,
  极品: 1_000_000,
} as const;

const ACTIVE_MEMBER_STATES = new Set(['在宗', '外派', '闭关', '负伤']);
const BACKPACK_TYPES = new Set<BackpackItem['类型']>([
  '丹药',
  '材料',
  '功法',
  '杂物',
  '灵石',
  '武器',
  '法器',
  '头盔',
  '衣袍',
  '腰带',
  '靴子',
  '项链',
  '戒指',
  '护腕',
]);

function nonNegativeInteger(value: unknown): number {
  return Math.max(0, Math.round(Number(value) || 0));
}

export function spiritStonesToBase(stones: Partial<SpiritStones> = {}): number {
  return (Object.entries(SPIRIT_STONE_RATES) as [keyof SpiritStones, number][]).reduce(
    (total, [grade, rate]) => total + nonNegativeInteger(stones[grade]) * rate,
    0,
  );
}

export function baseToSpiritStones(total: number): SpiritStones {
  let rest = nonNegativeInteger(total);
  const 极品 = Math.floor(rest / SPIRIT_STONE_RATES.极品);
  rest %= SPIRIT_STONE_RATES.极品;
  const 上品 = Math.floor(rest / SPIRIT_STONE_RATES.上品);
  rest %= SPIRIT_STONE_RATES.上品;
  const 中品 = Math.floor(rest / SPIRIT_STONE_RATES.中品);
  const 下品 = rest % SPIRIT_STONE_RATES.中品;
  return { 下品, 中品, 上品, 极品 };
}

function addPayrollPackage(
  payrollPackage: PayrollPackage | undefined,
  count: number,
  totals: { stones: number; materials: Record<string, number> },
): void {
  if (!payrollPackage || count <= 0) return;
  totals.stones += spiritStonesToBase(payrollPackage.灵石) * count;
  for (const [name, quantity] of Object.entries(payrollPackage.物资)) {
    totals.materials[name] = (totals.materials[name] ?? 0) + nonNegativeInteger(quantity) * count;
  }
}

function payrollAvailability(
  sect: SectArchive,
  requiredStones: number,
  requiredMaterials: Record<string, number>,
): {
  paidStones: number;
  paidMaterials: Record<string, number>;
  owedMaterials: Record<string, number>;
} {
  const paidStones = Math.min(requiredStones, spiritStonesToBase(sect.仓库.灵石));
  const paidMaterials: Record<string, number> = {};
  const owedMaterials: Record<string, number> = {};
  for (const [name, required] of Object.entries(requiredMaterials)) {
    const item = sect.仓库.物资[name];
    const available = item ? Math.max(0, item.数量 - item.已预留) : 0;
    const paid = Math.min(required, available);
    paidMaterials[name] = paid;
    if (paid < required) owedMaterials[name] = required - paid;
  }
  return { paidStones, paidMaterials, owedMaterials };
}

export function buildPayrollPreview(sect: SectArchive): PayrollPreview {
  const totals = { stones: 0, materials: {} as Record<string, number> };
  const missing = new Set<string>();
  let participants = 0;

  for (const group of Object.values(sect.成员统计)) {
    const count = nonNegativeInteger(group.人数);
    participants += count;
    const payrollPackage = sect.俸禄.制度[group.俸禄档位];
    if (count > 0 && group.俸禄档位 && !payrollPackage) missing.add(`俸禄:${group.俸禄档位}`);
    addPayrollPackage(payrollPackage, count, totals);
  }

  for (const member of Object.values(sect.成员名册)) {
    if (!ACTIVE_MEMBER_STATES.has(member.状态)) continue;
    participants += 1;
    const payrollPackage = sect.俸禄.制度[member.俸禄档位];
    if (member.俸禄档位 && !payrollPackage) missing.add(`俸禄:${member.俸禄档位}`);
    addPayrollPackage(payrollPackage, 1, totals);
    if (member.津贴档位) {
      const allowancePackage = sect.俸禄.津贴制度[member.津贴档位];
      if (!allowancePackage) missing.add(`津贴:${member.津贴档位}`);
      addPayrollPackage(allowancePackage, 1, totals);
    }
  }

  const availability = payrollAvailability(sect, totals.stones, totals.materials);
  return {
    结算期: sect.俸禄.当前结算期,
    参与人数: participants,
    应发灵石: baseToSpiritStones(totals.stones),
    应发灵石折合下品: totals.stones,
    可发灵石折合下品: availability.paidStones,
    欠付灵石折合下品: totals.stones - availability.paidStones,
    应发物资: totals.materials,
    可发物资: availability.paidMaterials,
    欠付物资: availability.owedMaterials,
    缺失档位: [...missing].sort((a, b) => a.localeCompare(b, 'zh-CN')),
  };
}

function applyWarehousePayment(
  sect: SectArchive,
  paidStones: number,
  paidMaterials: Record<string, number>,
): void {
  sect.仓库.灵石 = baseToSpiritStones(spiritStonesToBase(sect.仓库.灵石) - paidStones);
  for (const [name, paid] of Object.entries(paidMaterials)) {
    const item = sect.仓库.物资[name];
    if (!item || paid <= 0) continue;
    item.数量 = Math.max(item.已预留, item.数量 - paid);
  }
}

export function settleSectPayroll(sect: SectArchive): PayrollSettlementResult {
  const period = sect.俸禄.当前结算期.trim();
  if (!period) return { ok: false, reason: '尚未设置当前结算期' };
  if (sect.俸禄.最近全宗结算期 === period) return { ok: false, reason: '本期俸禄已经结算' };

  const preview = buildPayrollPreview(sect);
  const next = structuredClone(sect);
  applyWarehousePayment(next, preview.可发灵石折合下品, preview.可发物资);
  next.俸禄.最近全宗结算期 = period;
  next.俸禄.本期账单 = {
    结算期: period,
    参与人数: preview.参与人数,
    应发灵石: preview.应发灵石折合下品,
    实发灵石: preview.可发灵石折合下品,
    欠付灵石: preview.欠付灵石折合下品,
    应发物资: structuredClone(preview.应发物资),
    实发物资: structuredClone(preview.可发物资),
    欠付物资: structuredClone(preview.欠付物资),
    结算时间: period,
  };

  if (preview.欠付灵石折合下品 > 0 || Object.keys(preview.欠付物资).length > 0) {
    next.俸禄.欠俸[period] = {
      灵石折合下品: preview.欠付灵石折合下品,
      物资: structuredClone(preview.欠付物资),
    };
  } else {
    delete next.俸禄.欠俸[period];
  }

  next.财政.本期支出折合下品 += preview.可发灵石折合下品;
  next.财政.支出去向.弟子俸禄 = (next.财政.支出去向.弟子俸禄 ?? 0) + preview.可发灵石折合下品;
  next.仓库.流水[`俸禄结算·${period}`] = {
    时间: period,
    类型: '俸禄',
    内容: `向${preview.参与人数}名成员结算俸禄`,
    数量: -preview.可发灵石折合下品,
    经手人: '',
    原因: preview.欠付灵石折合下品 > 0 || Object.keys(preview.欠付物资).length > 0 ? '库存不足，部分结算' : '全额结算',
  };
  return { ok: true, sect: next, preview };
}

function personalPayrollPackage(sect: SectArchive): {
  totals: { stones: number; materials: Record<string, number> };
  missing: string[];
} {
  const totals = { stones: 0, materials: {} as Record<string, number> };
  const missing: string[] = [];
  const rank = sect.个人档案.俸禄档位 || sect.个人档案.身份;
  const payrollPackage = sect.俸禄.制度[rank];
  if (rank && !payrollPackage) missing.push(`俸禄:${rank}`);
  addPayrollPackage(payrollPackage, 1, totals);
  const allowance = sect.个人档案.津贴档位;
  if (allowance) {
    const allowancePackage = sect.俸禄.津贴制度[allowance];
    if (!allowancePackage) missing.push(`津贴:${allowance}`);
    addPayrollPackage(allowancePackage, 1, totals);
  }
  return { totals, missing };
}

function warehouseItemToBackpack(item: SectArchive['仓库']['物资'][string], quantity: number): BackpackItem {
  const type = BACKPACK_TYPES.has(item.类型 as BackpackItem['类型']) ? (item.类型 as BackpackItem['类型']) : '杂物';
  return {
    描述: item.描述,
    数量: quantity,
    类型: type,
    品阶: item.品阶,
    属性: '',
    属性加成: '',
    状态: item.状态,
  };
}

export function claimPersonalPayroll(data: RootData, sectName: string): PersonalPayrollResult {
  const sect = data.宗门档案[sectName];
  if (!sect) return { ok: false, reason: '当前宗门档案不存在' };
  const period = sect.俸禄.当前结算期.trim();
  if (!period) return { ok: false, reason: '尚未设置当前结算期' };
  if (sect.个人档案.最近领取俸禄期 === period) return { ok: false, reason: '本期个人俸禄已经领取' };

  const { totals, missing } = personalPayrollPackage(sect);
  if (missing.length > 0) return { ok: false, reason: `俸禄配置缺失：${missing.join('、')}` };
  const availability = payrollAvailability(sect, totals.stones, totals.materials);
  const next = structuredClone(data);
  const nextSect = next.宗门档案[sectName];
  applyWarehousePayment(nextSect, availability.paidStones, availability.paidMaterials);
  next.主角.灵石 += availability.paidStones;

  for (const [name, quantity] of Object.entries(availability.paidMaterials)) {
    if (quantity <= 0) continue;
    const existing = next.主角.背包[name];
    if (existing) {
      existing.数量 += quantity;
    } else {
      next.主角.背包[name] = warehouseItemToBackpack(nextSect.仓库.物资[name], quantity);
    }
  }

  const owedStones = totals.stones - availability.paidStones;
  nextSect.个人档案.最近领取俸禄期 = period;
  const debtKey = `个人·${next.主角.名称 || '主角'}·${period}`;
  if (owedStones > 0 || Object.keys(availability.owedMaterials).length > 0) {
    nextSect.俸禄.欠俸[debtKey] = {
      灵石折合下品: owedStones,
      物资: structuredClone(availability.owedMaterials),
    };
  }
  nextSect.仓库.流水[`个人俸禄·${next.主角.名称 || '主角'}·${period}`] = {
    时间: period,
    类型: '俸禄',
    内容: `${next.主角.名称 || '主角'}领取个人俸禄`,
    数量: -availability.paidStones,
    经手人: next.主角.名称,
    原因: owedStones > 0 || Object.keys(availability.owedMaterials).length > 0 ? '库存不足，部分领取' : '全额领取',
  };

  return {
    ok: true,
    data: next,
    实发灵石折合下品: availability.paidStones,
    实发物资: availability.paidMaterials,
    欠付灵石折合下品: owedStones,
    欠付物资: availability.owedMaterials,
  };
}
